blacksmith_village_intro.nodes:
[
{
"speaker": "Village Smithy",
"text": "You’re the first new face I’ve seen all cycle. Come close — let’s have a proper word before the forge gets crowded.",
"choices": [
{"text": "I didn’t come for talk. I came for work.", "next_node": 1},
{"text": "You look like the sort of person who knows what’s going on around here.", "next_node": 2}
]

deep_warden_greeting.nodes:
[
{
"speaker": "Deep Warden",
"text": "A visitor. Look at that -- the strata brightened the moment you landed. The Deep Root knows when someone is watching. Welcome to the camp, traveler.",
"choices": [
{"text": "Where are we exactly?", "next_node": 1},
{"text": "Why is the rock glowing?", "next_node": 2},
{"text": "Do you have work for me?", "next_node": 3},
{"text": "Farewell.", "next_node": -1}
]

jeweler_haven_intro.nodes:
[
{
"speaker": "Haven Jeweler",
"text": "Do wash your hands first, dear. Half this bench is cut pearl and the other half is patience, and I have less patience than cut pearl.",
"choices": [
{"text": "What do you sell from this bench?", "next_node": 1},
{"text": "You look like you know where the money is.", "next_node": 2}
]

merchant_greeting.nodes:
[
{
"speaker": "Merchant",
"text": "Welcome to my shop! I carry only the finest goods — weapons, armor, potions. Take a look around.",
"choices": [
{"text": "Show me your wares.", "next_node": 1},
{"text": "Just passing through. Farewell.", "next_node": -1}
]

sundered_ferry_talk.nodes:
[
{
"speaker": "Old Brack",
"text": "Tide's turning. You crossing, or just gawking at the wreck? The barque runs the strait six sailings a day -- moor pin to the seaward buoy and back. Two coin if you'd rather I row you out of schedule.",
"choices": [
{"text": "Tell me about the wreck shoal.", "next_node": 1},
{"text": "What happened to the crossing?", "next_node": 2},
{"text": "Any work going?", "next_node": 3},
{"text": "Farewell.", "next_node": -1}
]

sundered_salvor_talk.nodes:
[
{
"speaker": "Mag",
"text": "You'll be wanting rope, boots, and nerve. The shoal takes all three. I mark what the tide gives back and file what it keeps -- the good stuff is still in the barque's hold, under the wet.",
"choices": [
{"text": "The barque's hold is full?", "next_node": 1},
{"text": "What do you sell?", "next_node": 2},
{"text": "Any work going?", "next_node": 3},
{"text": "Farewell.", "next_node": -1}
]

tidewright_fenwick_intro.nodes:
[
{
"speaker": "Haven Tidewright",
"text": "Mind the tar bucket, the yard's wet through. Half this village's fence is my hand and the other half is what the tide takes back come the next blow, and I drink to both of them the same.",
"choices": [
{"text": "What does a plankwright sell?", "next_node": 1},
{"text": "You keep the strait's moor banks in working order?", "next_node": 2}
]

village_elder_greeting.nodes:
[
{
"speaker": "Village Elder",
"text": "Greetings, young one. You stand in the Village of Haven, a sanctuary at the edge of the Gloomwood. Few travelers find their way here.",
"choices": [
{"text": "What is this place?", "next_node": 1},
{"text": "Do you have work for me?", "next_node": 2},
{"text": "Farewell.", "next_node": -1}
]
